import { createApp } from "../src/app.ts";
import { ManualClock } from "../src/clock.ts";
import { sequentialIds } from "../src/ids.ts";
import { MemoryStore } from "../src/store/memory.ts";
import type { Hono } from "hono";
import type { AppEnv } from "../src/http/env.ts";

type App = Hono<AppEnv>;

async function call(
  app: App,
  actor: string,
  token: string | undefined,
  method: string,
  path: string,
  body: unknown,
  expectedStatus: number,
): Promise<Response> {
  const headers: Record<string, string> = {};
  if (token !== undefined) headers["authorization"] = `Bearer ${token}`;
  if (body !== undefined) headers["content-type"] = "application/json";
  const init: RequestInit = { method, headers };
  if (body !== undefined) init.body = JSON.stringify(body);
  const res = await app.request(path, init);
  console.log(`[probe] ${actor} ${method} ${path} -> ${res.status} (expected ${expectedStatus})`);
  return res;
}

describe("authz.permission-evaluation freshness guard", () => {
  it("a revoked collaborator is denied on the very next request", async () => {
    const deps = {
      store: new MemoryStore(),
      clock: new ManualClock(1_000_000_000_000),
      ids: sequentialIds(),
    };
    const app = createApp(deps);

    // Set up three users.
    expect((await call(app, "anon", undefined, "POST", "/users", { username: "owner", password: "ownerpass12", name: "Owner" }, 201)).status).toBe(201);
    expect((await call(app, "anon", undefined, "POST", "/users", { username: "target", password: "targetpass12" }, 201)).status).toBe(201);
    expect((await call(app, "anon", undefined, "POST", "/users", { username: "third", password: "thirdpass12" }, 201)).status).toBe(201);

    const ownerToken = (await (await call(app, "anon", undefined, "POST", "/sessions", { username: "owner", password: "ownerpass12" }, 201)).json()).token;
    const targetToken = (await (await call(app, "anon", undefined, "POST", "/sessions", { username: "target", password: "targetpass12" }, 201)).json()).token;

    // Owner creates a private repo and grants the target admin access.
    expect((await call(app, "owner", ownerToken, "POST", "/repos", { name: "repo", visibility: "private" }, 201)).status).toBe(201);
    expect((await call(app, "owner", ownerToken, "PUT", "/repos/owner/repo/collaborators/target", { role: "admin" }, 201)).status).toBe(201);

    // The target makes a request that evaluates their role, priming any per-session cache.
    expect((await call(app, "target", targetToken, "GET", "/repos/owner/repo/collaborators", undefined, 200)).status).toBe(200);

    // Owner revokes the target's access. If the route does not exist, Hono returns its
    // default text/plain 404, which means the precondition is absent.
    const revoke = await call(app, "owner", ownerToken, "DELETE", "/repos/owner/repo/collaborators/target", undefined, 204);
    if (
      revoke.status === 404 &&
      revoke.headers.get("content-type")?.startsWith("text/plain") &&
      (await revoke.clone().text()) === "404 Not Found"
    ) {
      throw new Error("probe not applicable: revoke route is absent");
    }
    expect(revoke.status).toBe(204);

    // The revoked user must not be able to perform an admin-only action now.
    const after = await call(app, "target", targetToken, "PUT", "/repos/owner/repo/collaborators/third", { role: "read" }, 404);
    expect(after.status).toBe(404);
  });
});
"}, "rationale": "The probe exercises A's premise that permission evaluation is fresh per request by creating a private repository, granting a collaborator admin access, having that collaborator make a request to prime any per-session role cache, then having the owner revoke them via A's DELETE route, and finally having the revoked collaborator attempt an admin-only action. In world A the fresh lookup sees the removed role and returns 404, while in A+B B's per-session role cache returns the stale admin role and allows the action (201), proving the disagreement. If the revoke route is absent (base or B), the DELETE returns Hono's default text/plain 404 and the probe throws n/a. The test also fails if A's revoke does not actually remove the collaborator, because the final request would then succeed."}

